<?php
declare(strict_types=1);
namespace MarketForecast\Tests;
use MarketForecast\AI\OpenAIProvider;
use PHPUnit\Framework\TestCase;
final class OpenAIProviderTest extends TestCase { public function testMockResponseIsValidated():void{$p=new OpenAIProvider('test','test', 'https://example.invalid', fn()=>['output_text'=>'{"direction":"NEUTRAL","probability_up":0.2,"probability_neutral":0.6,"probability_down":0.2,"expected_return_pct":0.1,"confidence":0.6,"reason_codes":["MIXED_SIGNAL"],"explanation":"fixture"}']);$r=$p->forecast(['rsi14'=>50],'2026-01-01T00:00:00+00:00');self::assertSame('NEUTRAL',$r['direction']);} public function testExplicitDirectionalAliasesNormalizeToScientificEnum():void{$p=new OpenAIProvider('test','test','https://example.invalid',fn()=>['output_text'=>'{"direction":"up","probability_up":0.7,"probability_neutral":0.2,"probability_down":0.1,"expected_return_pct":1.2,"confidence":0.7,"reason_codes":["POSITIVE_TREND"],"explanation":"fixture"}']);self::assertSame('BULLISH',$p->forecast(['rsi14'=>50],'2026-01-01T00:00:00+00:00')['direction']);} public function testObservedProviderReasonAliasesNormalizeToAllowedCodes():void{$p=new OpenAIProvider('test','test','https://example.invalid',fn()=>['output_text'=>'{"direction":"up","probability_up":0.56,"probability_neutral":0.24,"probability_down":0.20,"expected_return_pct":0.7,"confidence":0.65,"reason_codes":["CLOSE_ABOVE_SMAS","EMA_UPTREND","RSI_BULLISH","POSITIVE_MOMENTUM"],"explanation":"fixture"}']);self::assertSame(["POSITIVE_TREND","POSITIVE_TREND","RSI_SUPPORTIVE","POSITIVE_MOMENTUM"],$p->forecast(['rsi14'=>55],'2026-01-01T00:00:00+00:00')['reason_codes']);} }
